[{"ref_id":0,"title":"Field tilt: Overview","terms":"Field tilt","content":"Field tilt is the share of play in the final third that belongs to one team. Match Desk measures it as a team's share of all passes played into the attacking third: if Northgate play 30 such passes and Westmere 10, Northgate's field tilt is 75%."},{"ref_id":1,"title":"Expected goals (xG): Overview","terms":"Expected goals (xG)","content":"Expected goals measures the quality of a chance: the probability that a shot from that position becomes a goal, before considering how well it was struck. A shot worth 0.30 xG is scored about three times in ten."},{"ref_id":2,"title":"Lanterne Port FC (LPT): Overview","terms":"Lanterne Port FC (LPT)","content":"A fictional club in the Meridian League. Formation: 4-4-2. Style: low block and counter."},{"ref_id":3,"title":"Field tilt: Why it matters","terms":"Field tilt","content":"Possession counts every pass, including safe ones in a team's own half. Field tilt only counts the passes that put the opponent under pressure, so it tells you which side is pinning the other back. A team can have less of the ball and still dominate territory, which is common for direct and pressing teams."}]
{"kind":"reference","ref_id":0,"uri":"https://matchdesk-search-amgcx4ym3b4s6.search.windows.net/indexes/matchdesk-knowledge/docs/concepts-field-tilt-overview?$select=title%2Ccontent%2Cpage%2Cid%2Ccategory\u0026api-version=2026-08-01-preview\u0026allowUnsafeKeys=true","mimeType":"application/json","sourceData":{"id":"concepts-field-tilt-overview","title":"Field tilt: Overview","page":"Field tilt","category":"concept","content":"Field tilt is the share of play in the final third that belongs to one team. Match Desk measures it as a team\u0027s share of all passes played into the attacking third: if Northgate play 30 such passes and Westmere 10, Northgate\u0027s field tilt is 75%."}}
